function maxChunksToSorted(arr) {
  // A cut after position k is allowed exactly when the first k values are the k smallest values.
  const sorted = [...arr].sort((a, b) => a - b);
  let chunks = 0;
  for (let k = 1; k <= arr.length; k++) {
    const prefix = arr.slice(0, k).sort((a, b) => a - b);
    if (prefix.every((v, i) => v === sorted[i])) chunks++;
  }
  return chunks;
}

