function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const top = large ? (rand() < 0.5 ? 100000000 : 60) : (rand() < 0.2 ? 100000000 : 5);
  const arr = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  if (rand() < 0.35) return [arr];
  // Mostly sorted arrays with a few local swaps give many chunks.
  arr.sort((a, b) => a - b);
  const swaps = large ? Math.floor(rand() * 300) : Math.floor(rand() * 4);
  const reach = large ? 1 + Math.floor(rand() * 30) : 3;
  for (let s = 0; s < swaps; s++) {
    const i = Math.floor(rand() * n);
    const j = Math.min(n - 1, i + Math.floor(rand() * reach));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return [arr];
}
